int tomoyo_mount_acl(struct tomoyo_request_info *r, char *dev_name,
                     struct path *dir, char *type, unsigned long flags)
{
    struct super_block *sb;
    int error = -EINVAL;

    r->target = dev_name;
    r->filename = dir->d_path.name;
    r->type = type;
    r->flags = flags;

    sb = get_filesystem_type(type, flags);
    if (!sb)
        return -ENODEV;

    if (flags & MS_RDONLY) {
        if (sb->s_flags & MS_RDONLY)
            error = 0;
        else
            error = -EROFS;
    } else {
        error = 0;
    }

    if (!error) {
        tomoyo_audit_log(r, TOMOYO_TYPE_MOUNT_ACL, dev_name,
                          dir->d_path.name, type);
    }

    put_super(sb);
    return error;
}

