int tomoyo_mount_acl_check(struct tomoyo_request_info *r, char *dev_name,
                             struct path *dir, char *type, unsigned long flags)
{
    struct super_block *sb;
    int error = -EINVAL;

    if (!dir || !dir->dentry || !dir->mnt)
        return error;

    sb = dir->mnt->mnt_sb;
    if (!sb)
        return error;

    if (strcmp(sb->s_type->name, type) != 0)
        return error;

    r->profile = tomoyo_get_profile(current->security);
    r->operation = TOMOYO_OPERATION_MOUNT;

    if (dev_name) {
        r->name[0] = dev_name;
        error = tomoyo_check_acl(r, TOMOYO_TYPE_MOUNT_ON_DEVICE);
    } else {
        r->name[0] = "";
        error = tomoyo_check_acl(r, TOMOYO_TYPE_MOUNT_ON_PATH);
    }

    if (error)
        return error;

    r->name[1] = type;
    return tomoyo_check_acl(r, TOMOYO_TYPE_MOUNT_FILESYSTEM);
}

int tomoyo_mount_acl(struct tomoyo_request_info *r, char *dev_name,
                     struct path *dir, char *type, unsigned long flags)
{
    struct super_block *sb;
    int error = -EINVAL;

    if (!dir || !dir->dentry || !dir->mnt)
        goto out;

    sb = dir->mnt->mnt_sb;
    if (!sb)
        goto out;

    r->operation = TOMOYO_OPERATION_MOUNT;
    r->pathname[0] = dev_name;
    r->pathname[1] = type;
    r->pathname[2] = NULL;

    if (flags & MS_REMOUNT) {
        error = tomoyo_path_number(r, dir, TOMOYO_ACTION_MOUNT_REMOUNT);
        goto out;
    }

    if (!(flags & MS_BIND) && !dev_name) {
        error = tomoyo_path_number(r, dir, TOMOYO_ACTION_MOUNT_NO_DEVICE);
        goto out;
    }

    error = tomoyo_path_number(r, dir, TOMOYO_ACTION_MOUNT);
    if (error)
        goto out;

    error = 0;
out:
    return error;
}

int tomoyo_mount_acl_check(struct tomoyo_request_info *r, char *dev_name,
                            struct path *dir, char *type, unsigned long flags)
{
    struct super_block *sb;
    int error;

    r->operation = TOMOYO_OPERATION_MOUNT;
    r->filename = dev_name;
    r->pathname = dir->d_path.name;
    r->pathname2 = type;

    error = tomoyo_get_upper_path(r, dir);
    if (error)
        return error;

    sb = get_super(dev_name);
    if (sb) {
        put_super(sb);
        if (flags & MS_RDONLY)
            r->flags |= 1;
        else
            r->flags &= ~1;
        error = tomoyo_check_acl(r);
        if (error)
            return error;
    } else {
        if (dev_name && dev_name[0]) {
            error = tomoyo_realpath_from_path(r, dir);
            if (error)
                return error;
        }
    }

    return 0;
}
